function plot_numerical_results(T,MValues)
%PLOT_NUMERICAL_RESULTS Plot the numerical certification tradeoffs.
%
% Inputs:
%   T       - Table generated by run_numerical_analysis.m
%   MValues - Vector containing the evaluated numbers of targets
%
% Outputs:
%   numerical_tradeoffs.pdf - Vector-format publication figure
%   numerical_tradeoffs.png - 600 dpi raster figure

figure( ...
    'Color','w', ...
    'Units','centimeters', ...
    'Position',[2 2 29 16]);

tiledlayout(2,2, ...
    'TileSpacing','compact', ...
    'Padding','compact');

% Distinct line and marker styles for the different M values.
styles = {'-o','--s','-.^',':d'};

% Grayscale tones preserve distinction in print together with line styles.
grayLevels = [0.10 0.32 0.54 0.72];

fields = { ...
    'pair_trigger_probability', ...
    'system_trigger_probability', ...
    'mean_system_normalized_time_conditional', ...
    'early_cert_probability'};

ylabs = { ...
    '$P_{\mathrm{pair}}$', ...
    '$P_{\mathrm{sys}}$', ...
    '$\mathrm{E}[\tau_{\mathrm{sys}}/K\mid\mathrm{success}]$', ...
    '$P_{\mathrm{early}}$'};

titles = { ...
    '$(a)\ \mathrm{Pairwise\ triggering}$', ...
    '$(b)\ \mathrm{System\!-\!level\ triggering}$', ...
    '$(c)\ \mathrm{Conditional\ certification\ time}$', ...
    '$(d)\ \mathrm{Early\ certification}$'};

for p = 1:4

    ax = nexttile;
    hold(ax,'on');

    % Plot the results for each number of assigned targets.
    for m = 1:numel(MValues)

        rows = T.M == MValues(m);
        y = T.(fields{p});

        plot( ...
            ax, ...
            T.rho(rows), ...
            y(rows), ...
            styles{m}, ...
            'LineWidth',1.2, ...
            'MarkerSize',4, ...
            'DisplayName',sprintf('$M=%d$',MValues(m)));

    end

    % The theoretical regime boundaries have different line styles.
    % Their labels appear only in the legend.
    xline( ...
        ax, ...
        1, ...
        '--', ...
        'Color',[0 0 0], ...
        'LineWidth',1.2, ...
        'DisplayName','$\rho=1$');

    xline( ...
        ax, ...
        2, ...
        ':', ...
        'Color',[0 0 0], ...
        'LineWidth',1.5, ...
        'DisplayName','$\rho=2$');

    xlabel( ...
        ax, ...
        '$\rho=\delta^*/\delta$', ...
        'Interpreter','latex');

    ylabel( ...
        ax, ...
        ylabs{p}, ...
        'Interpreter','latex');

    title( ...
        ax, ...
        titles{p}, ...
        'Interpreter','latex');

    xlim(ax,[0.5 3]);
    ylim(ax,[0 1.03]);

    grid(ax,'on');
    box(ax,'on');

    % Apply LaTeX rendering to the tick labels.
    ax.TickLabelInterpreter = 'latex';
    ax.FontSize = 9;

    % Place the legend in the bottom-right corner.
    legend( ...
        ax, ...
        'Location','southeast', ...
        'Interpreter','latex', ...
        'FontSize',8, ...
        'Box','on');

end

% Export the publication-ready vector figure.
exportgraphics( ...
    gcf, ...
    'numerical_tradeoffs.pdf', ...
    'ContentType','vector');

% Export a 600 dpi raster version.
exportgraphics( ...
    gcf, ...
    'numerical_tradeoffs.png', ...
    'Resolution',600);

end